import createClient from 'openapi-fetch'

import type { paths } from './schema'

// The typed API client. `paths` comes from schema.d.ts, generated by `bun run api:types`
// from __SERVER_DIR__/openapi.json; a request or response that drifts from the contract is a
// type error here. The origin is resolved explicitly because undici's `Request` (Vitest)
// refuses a bare path; in the browser it is the page's own origin, so every call is a
// relative /api call and needs no CORS. `fetch` is resolved per call, so tests can stub
// `globalThis.fetch`. Only feature/*/api/ files import this module (lint enforces it).
export const client = createClient<paths>({
  baseUrl: window.location.origin,
  fetch: (request) => globalThis.fetch(request),
})
